// Hand-rolled SPL Token transfer builder + Associated Token Account (ATA) PDA derivation.
// PURE module — no network. Byte-exact against @solana/web3.js v1 + @solana/spl-token v0.4.9
// (golden vectors in __tests__/solana-spl.test.ts, generated by .dev/sol-poc/09-spl-golden.mjs).
//
// Implements the offline-signed USDC payment shape: {AdvanceNonceAccount(ix0), Token.transfer(ix1)}
// with recentBlockhash = the payer's stored durable nonce. The Token Program instruction
// discriminator is a SINGLE BYTE u8 (unlike the System Program's u32 LE) — this is the Solana
// Token program's bincode convention.
//
// ATA PDA derivation uses the documented ProgramDerivedAddress algorithm: sha256 over
// (seeds ++ programId ++ 'ProgramDerivedAddress'), rejecting any result that decodes to a valid
// ed25519 point, iterating the bump seed 255→0. The on-curve check uses noble's ExtendedPoint.fromHex
// — the SAME primitive @solana/web3.js v1 delegates to, so the derivation matches exactly.

import { ed25519 } from '@noble/curves/ed25519';
import { sha256 } from '@noble/hashes/sha256';
import bs58 from 'bs58';
import { base58Decode32, encodeU32LE, encodeU64LE, SYSTEM_PROGRAM_BYTES } from './tx';
import { assembleMessage, type Instruction, SYSVAR_RECENT_BLOCKHASHES_ADDRESS } from './nonce';

/** SPL Token Program (the legacy TokenkegQ program that USDC/SPL fungibles use). */
export const TOKEN_PROGRAM_ADDRESS = 'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA';
/** Associated Token Account Program (creates ATAs; not directly invoked here but documented). */
export const ASSOCIATED_TOKEN_PROGRAM_ADDRESS = 'ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL';
/** USDC mainnet mint. The devnet mint differs — config surfaces in a later unit; this is the default. */
export const USDC_MINT_ADDRESS = 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v';
/** USDC has 6 decimals (1 USDC = 1_000_000 raw units). */
export const USDC_DECIMALS = 6;

const TOKEN_PROGRAM_BYTES = base58Decode32(TOKEN_PROGRAM_ADDRESS);
const ASSOCIATED_TOKEN_PROGRAM_BYTES = base58Decode32(ASSOCIATED_TOKEN_PROGRAM_ADDRESS);
const PDA_MARKER = new TextEncoder().encode('ProgramDerivedAddress');

// System Program AdvanceNonceAccount discriminator (u32 LE = 4).
const IX_ADVANCE_NONCE = 4;
// SPL Token `transfer` instruction index — a SINGLE u8 (Token program bincode convention), not u32.
const IX_TOKEN_TRANSFER = 3;

/**
 * Derive a Program-Derived Address: sha256(seeds ++ programId ++ 'ProgramDerivedAddress'). Throws if
 * the result decodes to a valid ed25519 point (PDAs must fall OFF the curve). Matches
 * @solana/web3.js PublicKey.createProgramAddressSync exactly (same sha256, same on-curve check).
 */
function createProgramAddress(seeds: Uint8Array[], programId: Uint8Array): Uint8Array {
  const parts: Uint8Array[] = [];
  for (const s of seeds) {
    if (s.length > 32) throw new Error('max seed length exceeded');
    parts.push(s);
  }
  parts.push(programId);
  parts.push(PDA_MARKER);
  let total = 0;
  for (const p of parts) total += p.length;
  const buf = new Uint8Array(total);
  let off = 0;
  for (const p of parts) { buf.set(p, off); off += p.length; }
  const hash = sha256(buf);
  // A PDA must NOT be a valid ed25519 public key. fromHex throws on an off-curve/incompliant point.
  try {
    ed25519.ExtendedPoint.fromHex(hash);
  } catch {
    return hash; // off-curve → valid PDA
  }
  throw new Error('invalid seeds: address must fall off the curve');
}

/**
 * Find the canonical PDA: iterate the bump seed 255→0 and return the first that derives off-curve.
 * Mirrors @solana/web3.js PublicKey.findProgramAddressSync. Returns {pubkey, bump}.
 */
function findProgramAddress(
  seeds: Uint8Array[],
  programId: Uint8Array,
): { pubkey: Uint8Array; bump: number } {
  for (let bump = 255; bump > 0; bump--) {
    try {
      const pubkey = createProgramAddress([...seeds, new Uint8Array([bump])], programId);
      return { pubkey, bump };
    } catch {
      continue;
    }
  }
  throw new Error('unable to find a viable program address nonce');
}

/**
 * Derive the Associated Token Account address for (wallet, mint) under the Token Program.
 * Seeds = [wallet(32), TOKEN_PROGRAM_ID(32), mint(32)], derived under the ASSOCIATED TOKEN PROGRAM
 * (NOT the Token Program itself — a common gotcha). Matches @solana/spl-token
 * getAssociatedTokenAddressSync exactly.
 */
export function deriveAta(walletAddress: string, mintAddress: string): Uint8Array {
  const wallet = base58Decode32(walletAddress);
  const mint = base58Decode32(mintAddress);
  return findProgramAddress(
    [wallet, TOKEN_PROGRAM_BYTES, mint],
    ASSOCIATED_TOKEN_PROGRAM_BYTES,
  ).pubkey;
}

/**
 * Build a Token Program `transfer` instruction (raw form). The owner authorizes moving `amount` raw
 * units from the source token account to the destination token account. Accounts:
 *   [0] source  — writable, nonsigner
 *   [1] dest    — writable, nonsigner
 *   [2] owner   — readonly, signer (authorizes the debit)
 * Data: u8(3) || u64 LE amount. The Token program discriminator is a single byte (not u32).
 */
export function buildSplTransferInstruction(
  sourceAta: Uint8Array,
  destAta: Uint8Array,
  owner: Uint8Array,
  amount: bigint,
): Instruction {
  if (amount < 0n) throw new Error('amount must be non-negative');
  const data: number[] = [];
  data.push(IX_TOKEN_TRANSFER); // u8 discriminator
  encodeU64LE(data, amount);
  return {
    programId: TOKEN_PROGRAM_BYTES,
    keys: [
      { pubkey: sourceAta, signer: false, writable: true },
      { pubkey: destAta, signer: false, writable: true },
      { pubkey: owner, signer: true, writable: false },
    ],
    data: new Uint8Array(data),
  };
}

/**
 * Build the {AdvanceNonceAccount(ix0), Token.transfer(ix1)} message for an offline-signed durable-nonce
 * SPL payment. One signer (the authority / fee payer / token owner). `recentBlockhash` is the payer's
 * stored nonce VALUE — not a live blockhash — which is what makes the signature stale-blockhash-immune.
 */
export function buildAdvanceAndSplTransferMessage(
  authority: Uint8Array,
  nonceAccount: Uint8Array,
  sourceAta: Uint8Array,
  destAta: Uint8Array,
  owner: Uint8Array,
  amount: bigint,
  storedNonce: Uint8Array,
): Uint8Array {
  if (amount < 0n) throw new Error('amount must be non-negative');

  // ix[0] AdvanceNonceAccount: SystemProgram, keys=[nonceAccount(W), SysvarRecentBlockhashes(ro),
  // authority(signer W)], data=u32(4). Reuse the same shape as nonce.ts.
  const advanceData: number[] = [];
  encodeU32LE(advanceData, IX_ADVANCE_NONCE);
  const sysvarRecentBlockhashes = base58Decode32(SYSVAR_RECENT_BLOCKHASHES_ADDRESS);

  const instructions: Instruction[] = [
    {
      programId: SYSTEM_PROGRAM_BYTES,
      keys: [
        { pubkey: nonceAccount, signer: false, writable: true },
        { pubkey: sysvarRecentBlockhashes, signer: false, writable: false },
        { pubkey: authority, signer: true, writable: true },
      ],
      data: new Uint8Array(advanceData),
    },
    buildSplTransferInstruction(sourceAta, destAta, owner, amount),
  ];
  return assembleMessage(authority, instructions, storedNonce);
}
